// ----------------------------------------------------------------------------------
// [MVU 核心规则引擎] - v1.0
// 描述：此脚本根据你的输入自动更新游戏世界的变量。请使用特定关键词来触发。
// 作者：LLM
// ----------------------------------------------------------------------------------

// --- 规则一：时间流逝与每日衰减 ---
// 触发条件：当你的输入包含“结束这一天”、“睡觉”、“进入第二天”时。
<if string="{{last_user_message}}" contains="结束这一天" or contains="睡觉" or contains="进入第二天">
    <eval>
        // 1. 获取当前变量值
        const current_day = {{get_message_variable::stat_data.day}};
        const current_countdown = {{get_message_variable::stat_data.countdown_to_final_day}};
        const catherine_power = {{get_message_variable::stat_data.catherine.magic_power}};

        // 2. 计算新值
        const new_day = current_day + 1;
        const new_countdown = current_countdown - 1;
        const new_catherine_power = Math.max(0, catherine_power - 4.5); // 确保魔力不会低于0

        // 3. 执行变量更新
        _.set('day', current_day, new_day);
        _.set('countdown_to_final_day', current_countdown, new_countdown);
        _.set('catherine.magic_power', catherine_power, new_catherine_power);
    </eval>
    [系统提示] 时间流逝... 新的一天到来了。凯瑟琳的气息似乎又微弱了一分。
</if>

// --- 规则二：BPA 兵力增强 ---
// 触发条件：当“天数”变量变为5的倍数时（在时间流逝后自动触发）。
// 注意：此规则会在“时间流逝”规则触发的同一回合内，在后台自动执行。
<if string="{{get_message_variable::stat_data.day}}" equals="5" or equals="10" or equals="15" or equals="20" or equals="25" or equals="30" or equals="35" or equals="40">
    <if string="{{get_message_variable::stat_data.bpa.military_power}}" lessThanOrEqual="{{get_message_variable::stat_data.day}} * 2.5 + 40"> // 防止重复触发
    <eval>
        // 1. 获取当前兵力
        const current_bpa_power = {{get_message_variable::stat_data.bpa.military_power}};
        // 2. 计算新兵力
        const new_bpa_power = current_bpa_power + 11.0;
        // 3. 更新变量
        _.set('bpa.military_power', current_bpa_power, new_bpa_power);
    </eval>
    [BPA动态] 在你看不到的地方，国家的战争机器正在转动。BPA获得了新的资源和人员，他们的力量增强了。
    </if>
</if>

// --- 规则三：{{user}} 魔法锻炼 ---
// 触发条件：当你的输入包含“冥想”、“练习魔法”、“锻炼”、“学习魔法”时。
<if string="{{last_user_message}}" contains="冥想" or contains="练习魔法" or contains="锻炼" or contains="学习魔法">
    <eval>
        // 1. 获取当前进度
        let current_progress = {{get_message_variable::stat_data.user.training_progress}};
        let current_power = {{get_message_variable::stat_data.user.magic_power}};
        let progress_gain = 10; // 默认为基础练习

        // 2. 判断是否有凯瑟琳指导，获得加成
        if ("{{last_user_message}}".includes("凯瑟琳") || "{{last_user_message}}".includes("母亲") || "{{last_user_message}}".includes("妈妈")) {
            progress_gain = 20;
        }

        const new_progress = current_progress + progress_gain;
        _.set('user.training_progress', current_progress, new_progress);

        // 3. 检查是否可以升级
        if (new_progress >= 100) {
            const new_power = current_power + 10.0;
            const remaining_progress = new_progress - 100;
            _.set('user.magic_power', current_power, new_power);
            _.set('user.training_progress', new_progress, remaining_progress);
        }
    </eval>
    // 根据是否有指导和是否升级，给出不同反馈
    <if string="{{last_user_message}}" contains="凯瑟琳" or contains="母亲" or contains="妈妈">
        [魔法锻炼] 在凯瑟琳的悉心指导下，你对魔法的理解加深了。锻炼进度大幅提升。
    <else>
        [魔法锻炼] 你进行了刻苦的魔法练习。锻炼进度提升了。
    </if>
    <if number="{{get_message_variable::stat_data.user.training_progress}}" lessThan="20" and number="{{get_message_variable::stat_data.user.magic_power}}" greaterThan="15">
        [力量突破!] 你的魔力积累达到了临界点，感觉身体内的魔力奔涌不息。你的魔力等级提升了！
    </if>
</if>


// --- 规则四：战斗检定后的状态更新 ---
// 触发条件：当你的输入包含“战斗胜利”或“战斗失败”时。这用于在战斗剧情后手动校准变量。
<if string="{{last_user_message}}" contains="战斗胜利">
    <eval>
        // 战斗胜利，轻微削弱BPA士气，或者让他们下次增援变慢。此处仅作标记。
        _.set('plot.last_bpa_action', '{{get_message_variable::stat_data.plot.last_bpa_action}}', '被击退');
    </eval>
    [系统提示] 你们成功击退了敌人，赢得了宝贵的喘息之机。
</if>
<if string="{{last_user_message}}" contains="战斗失败">
    <eval>
        // 战斗失败，凯瑟琳消耗额外魔力。
        const catherine_power = {{get_message_variable::stat_data.catherine.magic_power}};
        const new_catherine_power = Math.max(0, catherine_power - 10.0); // 额外惩罚性消耗
        _.set('catherine.magic_power', catherine_power, new_catherine_power);
    </eval>
    [系统提示] 一场艰苦的战斗，你们虽然勉强幸存，但代价是沉重的。凯瑟琳为了保护你，消耗了大量本已宝贵的魔力。
</if>

// ----------------------------------------------------------------------------------
// [引擎使用说明]
// 1. 战斗胜负的判断逻辑（总魔力 vs BPA兵力）由扮演AI（我）在“剧情流程”的指导下进行叙述和裁定。
// 2. 此脚本主要负责根据关键词【自动更新】角色的核心数值，扮演AI无需手动计算。
// 3. 您只需在对话中自然地融入关键词（如“今天结束了，我们去休息吧”或“我要在母亲的指导下练习魔法”），引擎便会为您处理一切。
// ----------------------------------------------------------------------------------

